select
a.diagnose_result_id,
a.channel_id,
a.ip,
a.chan_index,
a.check_time,
a.channel_result,
a.signal_result,
a.blur_result,
a.contrast_result,
a.bright_result,
a.dark_result,
a.chroma_result,
a.mono_result,
a.noise_result,
a.streak_result,
a.freeze_result,
a.shake_result,
a.flash_result,
a.scene_result,
a.cover_result,
a.ptz_result,
a.snapshot_url,
a.result_content,
a.width,
a.height,
a.diagnose_plan_id
from t_diagnose_result a
where 1 = 1
and a.diagnose_result_id =
    #{diagnoseResultId, jdbcType=BIGINT}

and a.channel_id = #{channelId, jdbcType=VARCHAR}
and a.ip = #{ip, jdbcType=VARCHAR}
and a.chan_index = #{chanIndex, jdbcType=VARCHAR}
and a.check_time = #{checkTime, jdbcType=TIMESTAMP}
and a.channel_result =
    #{channelResult, jdbcType=INTEGER}

and a.signal_result = #{signalResult, jdbcType=VARCHAR}

and a.blur_result = #{blurResult, jdbcType=VARCHAR}
and a.contrast_result =
    #{contrastResult, jdbcType=VARCHAR}

and a.bright_result = #{brightResult, jdbcType=VARCHAR}

and a.dark_result = #{darkResult, jdbcType=VARCHAR}
and a.chroma_result = #{chromaResult, jdbcType=VARCHAR}

and a.mono_result = #{monoResult, jdbcType=VARCHAR}
and a.noise_result = #{noiseResult, jdbcType=VARCHAR}
and a.streak_result = #{streakResult, jdbcType=VARCHAR}

and a.freeze_result = #{freezeResult, jdbcType=VARCHAR}

and a.shake_result = #{shakeResult, jdbcType=VARCHAR}
and a.flash_result = #{flashResult, jdbcType=VARCHAR}
and a.scene_result = #{sceneResult, jdbcType=VARCHAR}
and a.cover_result = #{coverResult, jdbcType=VARCHAR}
and a.ptz_result = #{ptzResult, jdbcType=VARCHAR}
and a.snapshot_url = #{snapshotUrl, jdbcType=VARCHAR}
and a.result_content =
    #{resultContent, jdbcType=VARCHAR}

and a.width = #{width, jdbcType=VARCHAR}
and a.height = #{height, jdbcType=VARCHAR}
and a.diagnose_plan_id =
    #{diagnosePlanId, jdbcType=VARCHAR}

select
a.diagnose_result_id,
a.channel_id,
a.ip,
a.chan_index,
a.check_time,
a.channel_result,
a.signal_result,
a.blur_result,
a.contrast_result,
a.bright_result,
a.dark_result,
a.chroma_result,
a.mono_result,
a.noise_result,
a.streak_result,
a.freeze_result,
a.shake_result,
a.flash_result,
a.scene_result,
a.cover_result,
a.ptz_result,
a.snapshot_url,
a.result_content,
a.width,
a.height,
diagnose_plan_id
from t_diagnose_result a
where 1 = 1
and a.diagnose_result_id =
    #{diagnoseResultId, jdbcType=BIGINT}

and a.channel_id = #{channelId, jdbcType=VARCHAR}
and a.ip = #{ip, jdbcType=VARCHAR}
and a.chan_index = #{chanIndex, jdbcType=VARCHAR}
and a.check_time = #{checkTime, jdbcType=TIMESTAMP}
and a.channel_result =
    #{channelResult, jdbcType=INTEGER}

and a.signal_result = #{signalResult, jdbcType=VARCHAR}

and a.blur_result = #{blurResult, jdbcType=VARCHAR}
and a.contrast_result =
    #{contrastResult, jdbcType=VARCHAR}

and a.bright_result = #{brightResult, jdbcType=VARCHAR}

and a.dark_result = #{darkResult, jdbcType=VARCHAR}
and a.chroma_result = #{chromaResult, jdbcType=VARCHAR}

and a.mono_result = #{monoResult, jdbcType=VARCHAR}
and a.noise_result = #{noiseResult, jdbcType=VARCHAR}
and a.streak_result = #{streakResult, jdbcType=VARCHAR}

and a.freeze_result = #{freezeResult, jdbcType=VARCHAR}

and a.shake_result = #{shakeResult, jdbcType=VARCHAR}
and a.flash_result = #{flashResult, jdbcType=VARCHAR}
and a.scene_result = #{sceneResult, jdbcType=VARCHAR}
and a.cover_result = #{coverResult, jdbcType=VARCHAR}
and a.ptz_result = #{ptzResult, jdbcType=VARCHAR}
and a.snapshot_url = #{snapshotUrl, jdbcType=VARCHAR}
and a.result_content =
    #{resultContent, jdbcType=VARCHAR}

and a.width = #{width, jdbcType=VARCHAR}
and a.height = #{height, jdbcType=VARCHAR}
and a.diagnose_plan_id =
    #{diagnosePlanId, jdbcType=VARCHAR}

SELECT c.camera_name as 'channelName', d.record_ip as 'ip', d.http_port as 'port', c.channel_num as 'chanIndex', c.is_control as 'devType', f.dict_note as 'devBrand', e.region_name as 'regionName', a.channel_result, a.check_time, a.result_content, a.signal_result, a.blur_result, a.contrast_result, a.bright_result, a.dark_result, a.chroma_result, a.mono_result, a.noise_result, a.streak_result, a.freeze_result, a.shake_result, a.flash_result, a.scene_result, a.cover_result, a.ptz_result, a.snapshot_url FROM t_diagnose_result a JOIN t_diagnose_plan b ON a.diagnose_plan_id=b.diagnose_plan_id LEFT JOIN t_camera_info c ON a.channel_id=c.monitor_id LEFT JOIN t_camera_recorder d ON c.record_id=d.record_id LEFT JOIN t_std_region e ON c.up_region_id=e.region_id LEFT JOIN t_dict_business f ON c.vendor_id=f.dict_code WHERE 1=1 AND b.plan_name like concat('%',#{planName, jdbcType=VARCHAR},'%')
AND c.camera_name like concat('%',#{channelName, jdbcType=VARCHAR},'%')
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
and a.diagnose_plan_id =#{diagnosePlanId,jdbcType=VARCHAR}

SELECT '信号丢失' as 'faultType', count(case WHEN a.signal_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '图像模糊' as 'faultType', count(case WHEN a.blur_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '对比度' as 'faultType', count(case WHEN a.contrast_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '图像过亮' as 'faultType', count(case WHEN a.bright_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '图像过暗' as 'faultType', count(case WHEN a.dark_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '图像偏色' as 'faultType', count(case WHEN a.chroma_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '黑白图像' as 'faultType', count(case WHEN a.mono_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '噪声干扰' as 'faultType', count(case WHEN a.noise_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '条纹干扰' as 'faultType', count(case WHEN a.streak_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '画面冻结' as 'faultType', count(case WHEN a.freeze_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '视频抖动' as 'faultType', count(case WHEN a.shake_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '视频剧变' as 'faultType', count(case WHEN a.flash_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '场景变换' as 'faultType', count(case WHEN a.scene_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '视频遮挡' as 'faultType', count(case WHEN a.cover_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '云台失控' as 'faultType', count(case WHEN a.ptz_result='2' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '登录失败' as 'faultType', count(case WHEN a.channel_result='3' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
UNION ALL
SELECT '取流异常' as 'faultType', count(case WHEN a.channel_result='4' then 1 else null end) as 'count' FROM t_diagnose_result a WHERE 1=1
and a.check_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
